/**
 * Rows for the areas whose rules "may apply" to a property: the suburb is in the area's list, but we cannot tell
 * whether the lot is inside the area. The rows are withheld on purpose (not served as the property's rules), so this
 * runs its own query per area and the route returns them beside, never inside, the property's provisions.
 *
 * Data: shared/may-apply-areas.json ({council:{SUBURB:[area]}}), generated by scripts/export_may_apply_areas.py from
 * data/chapter_scope/suburb_unconfirmed_areas.json. Nothing here is a hand-typed suburb or rule.
 *
 * prior-art-checked: lib/not-covered.ts is the council-wide withheld list (no rows, no suburb); no module queried
 * withheld rows by area.
 */
import mayApplyData from '@/shared/may-apply-areas.json';
import { normaliseSuburb, reasonText } from '@/lib/may-apply-reasons';
import type { MayApplyArea } from '@/components/compliance/DcpMayApplyBlock';

interface AreaRow {
  area_id: string;
  chapter_key: string;
  title: string;
  reason_code: string;
  applies_to_quote?: string | null;
  applies_to_page?: number | string | null;
  row_selector: { pdf_page_from?: number; pdf_page_to?: number; ids?: number[] };
}

const DATA = mayApplyData as Record<string, Record<string, AreaRow[]>>;

/** The areas listed for this council and suburb (empty when none). */
export function mayApplyAreasFor(councilSlug: string | null | undefined, suburb: string | null | undefined): AreaRow[] {
  const sub = normaliseSuburb(suburb);
  if (!councilSlug || !sub) return [];
  if (!Object.prototype.hasOwnProperty.call(DATA, councilSlug)) return [];
  const bySuburb = DATA[councilSlug];
  return Object.prototype.hasOwnProperty.call(bySuburb, sub) ? bySuburb[sub] : [];
}

/**
 * ONE select per area. Current, WITHHELD rows only (v2_is_actionable = FALSE): a row the property is already served
 * appears in the main list, so showing it here too would list it twice (1,585 of the draft's 1,814 rows were served,
 * 2026-10-20). TOC lines and rows with no layer are left out.
 */
export function buildMayApplySql(selectColumns: string): string {
  return `
    SELECT ${selectColumns}
    FROM regulatory_provisions rp
    WHERE rp.is_current = TRUE
      AND rp.source_council = $1
      AND rp.source_chapter_key = $2
      AND (rp.pdf_page BETWEEN $3::int AND $4::int OR rp.id = ANY($5::bigint[]))
      AND (rp.v2_provision_type IS NULL OR rp.v2_provision_type != 'TOC')
      AND rp.v2_dcp_layer IS NOT NULL
      AND rp.v2_is_actionable = FALSE
    ORDER BY rp.pdf_page, rp.id
    LIMIT 400`;
}

type Query = (sql: string, params: unknown[]) => Promise<{ rows: any[] }>;

/**
 * The may-apply entries for the response. A failed lookup returns the area with provisions: null (the block then says
 * it could not load), never an empty list that would read as "no rules".
 */
export async function loadMayApply(
  query: Query,
  opts: { councilSlug: string | null; suburb: string | null | undefined; selectColumns: string; mapRow: (row: any) => any },
): Promise<MayApplyArea[]> {
  const areas = mayApplyAreasFor(opts.councilSlug, opts.suburb);
  if (areas.length === 0 || !opts.councilSlug) return [];
  const sql = buildMayApplySql(opts.selectColumns);
  const suburb = normaliseSuburb(opts.suburb);
  const out: MayApplyArea[] = [];
  for (const a of areas) {
    const sel = a.row_selector ?? {};
    const hasRange = Number.isInteger(sel.pdf_page_from) && Number.isInteger(sel.pdf_page_to);
    // An empty range is (1, 0) so BETWEEN matches nothing; an area with neither selector matches nothing.
    const params = [opts.councilSlug, a.chapter_key, hasRange ? sel.pdf_page_from : 1, hasRange ? sel.pdf_page_to : 0, sel.ids ?? []];
    let provisions: any[] | null;
    try {
      provisions = (await query(sql, params)).rows.map(opts.mapRow);
      // No withheld rows left (e.g. the area has since been outlined and its rows served): nothing may-apply to show.
      if (provisions.length === 0) continue;
    } catch (err) {
      console.error(`[may-apply] lookup failed for ${a.area_id}:`, err);
      provisions = null;
    }
    out.push({
      area_id: a.area_id,
      chapter_key: a.chapter_key,
      title: a.title,
      reason_code: a.reason_code,
      reason_text: reasonText(a.reason_code) ?? '',
      applies_to_quote: a.applies_to_quote ?? null,
      applies_to_page: a.applies_to_page ?? null,
      suburb,
      provisions,
    });
  }
  return out;
}
